// The service worker: it keeps the lexicon on the device, so that it opens at once, searches without
// waiting for the network, and works offline. Generated by scripts/build.py from src/sw.js: the
// version is a hash of the files below, so any change to them replaces the saved copies.
const VERSION = '3e7e708de4c1';
const CORE = 'lexicon-core-' + VERSION;   // the pages and files every visit needs, saved when the worker installs
const PAGES = 'lexicon-pages';            // entry and word pages, saved as they are read
const PAGES_MAX = 600;
const FILES = ["assets/fonts/alegreya-sans-400.woff2","assets/fonts/alegreya-sans-500.woff2","assets/fonts/alegreya-sans-700.woff2","assets/fonts/lexicon-serif-400-italic.woff2","assets/fonts/lexicon-serif-400.woff2","assets/fonts/lexicon-serif-700-italic.woff2","assets/fonts/lexicon-serif-700.woff2","assets/icons/icon-180.png","assets/icons/icon-192.png","assets/icons/icon-512.png","assets/lexicon.css","assets/lexicon.js","assets/search-data.js","assets/search.js","how-we-decide.html","index.html","k/aedificatio.html","k/computatra.html","k/corpus.html","k/culina.html","k/domus-structura.html","k/domus.html","k/ecclesia.html","k/labor.html","k/ludi.html","k/natura.html","k/officina.html","k/pecunia.html","k/res-publica.html","k/schola.html","k/sermo.html","k/tempus.html","k/urbs.html","k/vectura.html","k/verba.html","k/vestitus.html","manifest.webmanifest","rulings.html"];

self.addEventListener('install', event => {
  event.waitUntil(caches.open(CORE)
    .then(cache => cache.addAll(FILES.map(file => new Request(file, { cache: 'reload' }))))
    .then(() => self.skipWaiting()));
});

self.addEventListener('activate', event => {
  event.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(key => key.startsWith('lexicon-core-') && key !== CORE).map(key => caches.delete(key))))
    .then(() => self.clients.claim()));
});

// The oldest saved pages make room for new ones.
async function trim(cache) {
  const keys = await cache.keys();
  await Promise.all(keys.slice(0, Math.max(0, keys.length - PAGES_MAX)).map(key => cache.delete(key)));
}

async function respond(request) {
  const url = new URL(request.url);
  // The front page is index.html however it is addressed (the folder, or with a search in its address).
  const key = url.pathname.endsWith('/') ? url.pathname + 'index.html' : url.pathname;
  const core = await caches.open(CORE);
  const saved = await core.match(key);
  if (saved) return saved;
  // Other pages: the saved copy at once, refreshed from the network for the next visit.
  const pages = await caches.open(PAGES);
  const copy = await pages.match(key);
  const fresh = fetch(request).then(response => {
    if (response.ok) pages.put(key, response.clone()).then(() => trim(pages));
    return response;
  });
  if (copy) { fresh.catch(() => {}); return copy; }
  try {
    return await fresh;
  } catch (error) {
    if (request.mode !== 'navigate') throw error;
    return new Response('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">'
      + '<title>Offline</title><body style="font:1.1rem/1.5 Georgia,serif;max-width:32em;margin:15vh auto;padding:0 20px">'
      + '<h1 style="font-size:1.4rem">This page is not saved on this device</h1>'
      + '<p>You are offline, and this page has not been opened here before. The search still works offline, '
      + 'and it shows each entry’s words and examples.</p><p><a href="' + self.registration.scope + 'index.html">Back to the search</a></p></body></html>',
      { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' } });
  }
}

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
  event.respondWith(respond(request));
});
